std::string get_runtime_directory() {
    const char* env_var = std::getenv("POLYBAR_RUNTIME_DIR");
    if (env_var) {
        return std::string(env_var) + "/polybar";
    }

    // Use XDG_RUNTIME_DIR if available
    const char* xdg_runtime_dir = std::getenv("XDG_RUNTIME_DIR");
    if (xdg_runtime_dir) {
        return std::string(xdg_runtime_dir) + "/polybar";
    }

    // Fallback to a temporary directory
    char tmp_dir[PATH_MAX];
    if (std::snprintf(tmp_dir, sizeof(tmp_dir), "/tmp/polybar-%u", std::getuid()) <= 0) {
        return "/tmp/polybar";
    }

    return std::string(tmp_dir);
}
