public static Node createAndAppendNode(Document doc, String path) {
    // Check if the path is directly to the root
    if (path.equals("/")) {
        Node root = doc.getDocumentElement();
        if (root == null) {
            root = doc.createElement("root");
            doc.appendChild(root);
        }
        return root;
    }

    // Split the path into parent path and target
    int pos = path.indexOf('/');
    String parentPath = path.substring(0, pos);
    String target = path.substring(pos + 1);

    // Recursively ensure the parent node exists
    Node parentNode = createAndAppendNode(doc, parentPath);

    // Check if the target is an attribute or element
    if (target.startsWith("@")) {
        // Create attribute
        String attrName = target.substring(1);
        Attr attr = doc.createAttribute(attrName);
        parentNode.setAttributeNode(attr);
        return attr;
    } else {
        // Create element
        Element element = doc.createElement(target);
        parentNode.appendChild(element);
        return element;
    }
}
