/**
 * Perform a left bitwise rotation of an integer.
 *
 * @param value   the integer value to rotate
 * @param shift   the number of positions to rotate
 * @return the result of the left bitwise rotation
 */
public static int rotateLeft(int value, int shift) {
    // Calculate the effective shift within 32 bits
    int effectiveShift = shift & 0x1F; // 0x1F is 31, so we take modulo 32

    // Shift left by effectiveShift positions
    int leftShift = value << effectiveShift;

    // Calculate the number of positions to shift right
    int rightShift = 32 - effectiveShift;

    // Shift right by rightShift positions
    int rightShifted = value >>> rightShift;

    // Combine the two shifts using bitwise OR
    return leftShift | rightShifted;
}
