 * Executes JavaScript code within the context of an iframe's document.
 * @param code - The JavaScript code to be executed.
 */
export function executeIframeScript(code: string): void {
  const iframe = document.getElementById('iframe');
  if (!iframe) {
    throw new Error('iframe element not found');
  }

  const iframeDoc = iframe.contentDocument || iframe.contentWindow?.document;
  if (!iframeDoc) {
    throw new Error('iframe document not accessible');
  }

  const script = iframeDoc.createElement('script');
  script.textContent = code;
  iframeDoc.body.appendChild(script);
}
