func (t *TLS) HasVaryHeader(header http.Header, target string) bool {
	// Check if the 'Vary' header is present
	vary := header.Get("Vary")
	if vary == "" {
		return false
	}

	// Split the 'Vary' header by commas and check each value
	for _, value := range strings.Split(vary, ",") {
		// Trim whitespace and perform case-insensitive comparison
		trimmedValue := strings.TrimSpace(value)
		if strings.EqualFold(trimmedValue, target) {
			return true
		}
	}

	return false
}
